@layer components {
  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"], [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --choice-radius: var(--radius-sm);
    --choice-border-color: var(--border);
    --choice-checked-background: var(--primary);
    --choice-checked-border-color: var(--primary);
    --_choice-background: oklch(from var(--card) l c h / 0.72);
    border-radius: var(--choice-radius);
    background: var(--_choice-background);
    box-shadow: inset 0 0 0 1px var(--choice-border-color), var(--shadow-sm);
    color: currentColor;
    outline: none;
    transition-property: background-color, box-shadow, color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --choice-radius: 9999px;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:hover, [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:hover) {
    --choice-border-color: oklch(from var(--foreground) l c h / 0.25);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:is([data-checked], [data-indeterminate]), [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:is([data-checked], [data-indeterminate])) {
    --_choice-background: var(--choice-checked-background);
    --choice-border-color: var(--choice-checked-border-color);
    color: var(--primary-foreground);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:focus-visible, [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:focus-visible) {
    box-shadow: inset 0 0 0 1px var(--choice-border-color), var(--shadow-sm), 0 0 0 2px var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"][data-disabled], [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"][data-invalid], [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"][data-invalid]) {
    --choice-border-color: var(--destructive);
    box-shadow: inset 0 0 0 1px var(--choice-border-color), var(--shadow-sm), 0 0 0 1px var(--destructive);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"] [data-slot="indicator"], [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"] [data-slot="indicator"]) {
    color: currentColor;
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"] [data-slot="indicator"]) {
    border-radius: 9999px;
    background: var(--primary-foreground);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --_choice-radio-group-item-outline: none;
    outline-style: var(--_choice-radio-group-item-outline);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="indicator"]) {
    color: currentcolor;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]) {
    --_choice-checkbox-root-outline: none;
    outline-style: var(--_choice-checkbox-root-outline);
  }
}

@property --choice-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --choice-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --choice-checked-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --choice-checked-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Radio as RadioPrimitive } from "@base-ui/react/radio";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import type { RadioGroupProps, RadioProps } from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

// `orientation` is visual only — Base UI owns roving focus on both axes and exposes no such prop.
export function RadioGroup<TValue extends string = string>({ className, orientation = "vertical", ...props }: RadioGroupProps<TValue>) {
  return (
    <RadioGroupPrimitive<TValue>
      data-control-ui="radio-group"
      data-control-family="choice"
      data-choice-kind="radio-group"
      data-slot="root"
      data-orientation={orientation}
      className={cn(
        "flex gap-2 data-[orientation=horizontal]:flex-row data-[orientation=horizontal]:gap-4 data-[orientation=vertical]:flex-col",
        className,
      )}
      {...props}
    />
  );
}

export function Radio({ className, disabled, ...props }: RadioProps) {
  return (
    <RadioPrimitive.Root
      data-control-ui="radio-group"
      data-choice-kind="radio-group"
      data-slot="item"
      data-control-family="choice"
      disabled={disabled}
      className={cn(
        "group/radio relative inline-flex size-4 shrink-0 cursor-pointer items-center justify-center",
        "data-[disabled]:cursor-not-allowed",
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-control-ui="radio-group"
        data-control-family="choice"
        data-choice-kind="radio-group"
        data-slot="indicator"
        className="size-1.5 data-[unchecked]:hidden"
      />
    </RadioPrimitive.Root>
  );
}
